using System.Net;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed record ReceivedRequest(string Method, string Path, string? ContentType, string Body);

/// <summary>A local HTTP server standing in for the provider, so tests exercise real HTTP.</summary>
public sealed class FakeProvider : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly int statusCode;
    private readonly string responseBody;

    public FakeProvider(int statusCode, string responseBody)
    {
        this.statusCode = statusCode;
        this.responseBody = responseBody;

        var port = Random.Shared.Next(20000, 60000);
        while (true)
        {
            listener.Prefixes.Clear();
            listener.Prefixes.Add($"http://localhost:{port}/");
            try { listener.Start(); break; }
            catch (HttpListenerException) { port++; }
        }
        BaseAddress = new Uri($"http://localhost:{port}");
        _ = Task.Run(ServeAsync);
    }

    public Uri BaseAddress { get; }

    public List<ReceivedRequest> Requests { get; } = [];

    private async Task ServeAsync()
    {
        while (listener.IsListening)
        {
            HttpListenerContext context;
            try { context = await listener.GetContextAsync(); }
            catch (Exception) { return; }

            using var reader = new StreamReader(context.Request.InputStream);
            var body = await reader.ReadToEndAsync();
            lock (Requests)
            {
                Requests.Add(new ReceivedRequest(context.Request.HttpMethod, context.Request.Url!.AbsolutePath, context.Request.ContentType, body));
            }

            context.Response.StatusCode = statusCode;
            context.Response.ContentType = "application/json";
            var bytes = System.Text.Encoding.UTF8.GetBytes(responseBody);
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        }
    }

    public void Dispose() => listener.Close();
}
