using System.Net;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static async Task<(AuthorizationOutcome Outcome, FakeProvider Provider)> Authorize(int status, string body)
    {
        var provider = new FakeProvider(status, body);
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-42", new Money(12.5m, "eur"), CancellationToken.None);
        return (outcome, provider);
    }

    [Fact]
    public async Task The_authorization_is_posted_to_the_provider_as_json_with_reference_amount_and_currency()
    {
        var (_, provider) = await Authorize(200, """{"status":"approved"}""");
        using var _p = provider;

        var request = Assert.Single(provider.Requests);
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);

        using var json = JsonDocument.Parse(request.Body);
        var root = json.RootElement;
        Assert.Equal(["amount", "currency", "reference"], root.EnumerateObject().Select(p => p.Name).Order());
        Assert.Equal("ORD-42", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, provider) = await Authorize(200, """{"status":"approved"}""");
        provider.Dispose();

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, provider) = await Authorize(200, """{"status":"declined"}""");
        provider.Dispose();

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        var (outcome, provider) = await Authorize(200, """{"id":"a1","status":"approved","risk":{"score":3}}""");
        provider.Dispose();

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Theory]
    [InlineData("""{}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"result":"approved"}""")]
    [InlineData("null")]
    public async Task An_answer_that_does_not_clearly_say_approved_is_never_treated_as_approved(string body)
    {
        var (outcome, provider) = await Authorize(200, body);
        provider.Dispose();

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_payment_the_provider_refuses_with_402_is_a_decline_even_if_the_body_says_approved()
    {
        var (outcome, provider) = await Authorize(402, """{"status":"approved"}""");
        provider.Dispose();

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_with_an_error_body_is_a_decline()
    {
        var (outcome, provider) = await Authorize(402, """{"error":"insufficient_funds"}""");
        provider.Dispose();

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_instead_of_being_taken_for_a_decision(int status)
    {
        using var provider = new FakeProvider(status, """{"status":"approved"}""");
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var gateway = new HttpPaymentGateway(client);

        var error = await Assert.ThrowsAsync<HttpRequestException>(() =>
            gateway.AuthorizeAsync("ORD-42", new Money(1m, "EUR"), CancellationToken.None));
        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    [Fact]
    public async Task A_success_answer_that_is_not_json_is_an_error()
    {
        using var provider = new FakeProvider(200, "<html>oops</html>");
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var gateway = new HttpPaymentGateway(client);

        await Assert.ThrowsAnyAsync<JsonException>(() =>
            gateway.AuthorizeAsync("ORD-42", new Money(1m, "EUR"), CancellationToken.None));
    }
}
